<template>
  <section v-if="items.length" class="question-queue" aria-label="待问队列">
    <header><div><span class="queue-orbit" :class="{paused}">≡</span><strong>接下来</strong><span class="queue-count">{{ items.length }} / 5</span><span class="queue-state">{{ paused?'已暂停':busy?'当前问题结束后依次开始':'准备开始' }}</span></div><div><button v-if="paused" :disabled="disabled" @click="$emit('resume')">继续队列 ▶</button><button v-else @click="$emit('pause')">暂停队列 Ⅱ</button><button @click="expanded=!expanded" :aria-expanded="expanded">{{ expanded?'收起':'展开' }}</button></div></header>
    <p v-if="paused && reason" class="queue-reason">{{ reason }}</p>
    <TransitionGroup v-if="expanded" tag="ol" name="queue-item" class="queued-list"><li v-for="(item,index) in items" :key="item.id"><span class="queue-position">{{ String(index+1).padStart(2,'0') }}</span><div><strong :title="item.question">{{ item.question }}</strong><small>{{ item.datasetName }}</small></div><div class="queue-actions"><button :disabled="index===0" :aria-label="`提前第${index+1}个排队问题`" title="提前一位" @click="$emit('move-up',item.id)">↑</button><button :disabled="disabled" :aria-label="`编辑第${index+1}个排队问题`" title="移回输入框编辑" @click="$emit('edit',item.id)">↗</button><button :aria-label="`移除第${index+1}个排队问题`" title="从队列移除" @click="$emit('remove',item.id)">×</button></div></li></TransitionGroup>
    <footer><span aria-live="polite">{{ items.length }} 个问题待执行 · 保留提交时的数据集，执行时核对授权</span><button @click="$emit('clear')">清空队列</button></footer>
  </section>
</template>
<script setup>
import {ref} from 'vue'
defineProps({items:{type:Array,default:()=>[]},paused:Boolean,reason:String,busy:Boolean,disabled:Boolean})
defineEmits(['resume','pause','remove','edit','move-up','clear'])
const expanded=ref(true)
</script>
